## 4. Realistische Code-Beispiele

### Beispiel 1: Grundlegende Tabelle mit Sortierung
```tsx
import { DataTable } from '@company/design-system';

interface User {
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user' | 'guest';
  lastLogin: Date;
}

const users: User[] = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin', lastLogin: new Date('2023-01-15') },
  { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user', lastLogin: new Date('2023-02-20') },
];

const columns = [
  { key: 'name', header: 'Name', sortable: true },
  { key: 'email', header: 'Email' },
  {
    key: 'role',
    header: 'Role',
    sortable: true,
    render: (value: string) => (
      <span style={{ color: value === 'admin' ? 'red' : 'inherit' }}>
        {value.toUpperCase()}
      </span>
    )
  },
  {
    key: 'lastLogin',
    header: 'Last Login',
    sortable: true,
    render: (value: Date) => value.toLocaleDateString()
  }
];

function UserTable() {
  return (
    <DataTable
      data={users}
      columns={columns}
      sortable
      onRowClick={(user) => console.log('Selected user:', user)}
    />
  );
}
```

### Beispiel 2: Tabelle mit Pagination und Custom Empty State
```tsx
import { DataTable } from '@company/design-system';

interface Product {
  id: string;
  name: string;
  price: number;
  inStock: boolean;
}

const products: Product[] = []; // Empty array for demonstration

const columns = [
  { key: 'name', header: 'Product Name', sortable: true },
  {
    key: 'price',
    header: 'Price',
    render: (value: number) => `$${value.toFixed(2)}`
  },
  {
    key: 'inStock',
    header: 'Availability',
    render: (value: boolean) => (
      <span style={{ color: value ? 'green' : 'red' }}>
        {value ? 'In Stock' : 'Out of Stock'}
      </span>
    )
  }
];

function ProductTable() {
  return (
    <DataTable
      data={products}
      columns={columns}
      pagination
      pageSize={5}
      emptyState={
        <div style={{ padding: '2rem', textAlign: 'center' }}>
          <h3>No products found</h3>
          <p>Try adjusting your search filters</p>
          <button onClick={() => window.location.reload()}>Reset Filters</button>
        </div>
      }
    />
  );
}
```

### Beispiel 3: Komplexe Tabelle mit Sticky Header und Custom Rendering
```tsx
import { DataTable } from '@company/design-system';

interface Order {
  id: string;
  customer: {
    name: string;
    email: string;
  };
  items: Array<{
    name: string;
    quantity: number;
    price: number;
  }>;
  total: number;
  status: 'pending' | 'processing' | 'shipped' | 'delivered';
  createdAt: Date;
}

const orders: Order[] = /* ... large dataset ... */;

const columns = [
  { key: 'id', header: 'Order ID', width: 120 },
  {
    key: 'customer',
    header: 'Customer',
    render: (value: Order['customer']) => (
      <div>
        <div>{value.name}</div>
        <div style={{ fontSize: '0.8em', color: '#666' }}>{value.email}</div>
      </div>
    )
  },
  {
    key: 'items',
    header: 'Items',
    render: (items: Order['items']) => (
      <ul style={{ margin: 0, paddingLeft: '1rem' }}>
        {items.map((item, i) => (
          <li key={i}>
            {item.quantity}x {item.name}
          </li>
        ))}
      </ul>
    )
  },
  {
    key: 'total',
    header: 'Total',
    render: (value: number) => `$${value.toFixed(2)}`,
    sortable: true
  },
  {
    key: 'status',
    header: 'Status',
    sortable: true,
    render: (value: Order['status']) => {
      const statusColors = {
        pending: '#ff9800',
        processing: '#2196f3',
        shipped: '#4caf50',
        delivered: '#8bc34a'
      };
      return (
        <span style={{ color: statusColors[value] }}>
          {value.charAt(0).toUpperCase() + value.slice(1)}
        </span>
      );
    }
  },
  {
    key: 'createdAt',
    header: 'Order Date',
    render: (value: Date) => value.toLocaleDateString(),
    sortable: true
  }
];

function OrderTable() {
  return (
    <div style={{ height: '500px', overflow: 'auto' }}>
      <DataTable
        data={orders}
        columns={columns}
        sortable
        pagination
        pageSize={20}
        stickyHeader
        striped
        onRowClick={(order) => navigateToOrderDetail(order.id)}
      />
    </div>
  );
}
```

